      }
    },
    "ongoing_costs": {
      "annual_legal_retainer": {
        "range": "€60K - €120K",
        "factors": "Regulatory updates, incident response"
      },
      "compliance_monitoring": {
        "range": "€45K - €85K",
        "factors": "Automated tools, manual reviews, reporting"
      },
      "audit_costs": {
        "range": "€35K - €70K",
        "factors": "External audits, internal compliance reviews"
      }
    }
  },
  "enforcement_trends": {
    "gdpr_fines_2024": {
      "total_fines": "€2.1B across EU",
